window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-57584b453ec449f8"]={"versions": [{"id": "FIG-57584b453ec449f8", "releases": ["R1.5.1", "R19-03", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Signallaufzeitmessung (Propagation Delay Measurement, Pdelay) im AUTOSAR Time Synchronization Protocol (PRS_TimeSyncProtocol / IEEE 802.1AS bzw. gPTP-Mechanismus). Es spezifiziert den nachrichtengestützten Punkt-zu-Punkt-Messablauf zur Bestimmung der Signallaufzeit über eine physikalische Netzwerkverbindung zwischen zwei direkt benachbarten Netzknoten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Peer Delay Initiator</strong>: Messinitiierender Netzknoten (Zeitsynchronisations-Endpunkt oder Switch-Port), sendet die Messanforderung und empfängt Rückmeldungen.</li>\n<li><strong>Peer Delay Responder</strong>: Antwortender Nachbarknoten, nimmt Anforderungen entgegen und übermittelt Messzeitstempel.</li>\n<li><strong>Schnittstellen / Nachrichten</strong>:</li>\n<li><code>Pdelay_Req()</code>: Anforderungsnachricht vom Initiator an den Responder.</li>\n<li><code>Pdelay_Resp(t2)</code>: Antwortnachricht vom Responder an den Initiator mit dem Empfangszeitstempel <code>t2</code>.</li>\n<li><code>Pdelay_Resp_Follow_Up(t3)</code>: Nachfolgenachricht (Two-Step-Verfahren) vom Responder an den Initiator mit dem Sendezeitstempel <code>t3</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <strong>Peer Delay Initiator</strong> erfasst beim Absenden der Anforderung <code>Pdelay_Req()</code> den Sendezeitstempel <code>t1</code> (<code>Get egress timestamp t1</code>).</li>\n<li>Der <strong>Peer Delay Responder</strong> empfängt die Anforderung und erfasst den Eingangszeitstempel <code>t2</code> (<code>Get ingress timestamp t2</code>).</li>\n<li>Der <strong>Peer Delay Responder</strong> sendet die Antwortnachricht <code>Pdelay_Resp(t2)</code> zurück, welche den Zeitstempel <code>t2</code> transportiert, und erfasst beim Absenden den Sendezeitstempel <code>t3</code> (<code>Get egress timestamp t3</code>).</li>\n<li>Der <strong>Peer Delay Initiator</strong> erfasst beim Empfang der Antwortnachricht den lokalen Eingangszeitstempel <code>t4</code> (<code>Get ingress timestamp t4</code>).</li>\n<li>Der <strong>Peer Delay Responder</strong> sendet abschließend die Nachricht <code>Pdelay_Resp_Follow_Up(t3)</code>, die den Zeitstempel <code>t3</code> an den Initiator übermittelt.</li>\n<li>Dem Initiator liegen nach Abschluss des Austauschs alle vier Zeitstempel (<code>t1</code>, <code>t2</code>, <code>t3</code>, <code>t4</code>) zur Berechnung der One-Way-Signallaufzeit (Propagationsverzögerung) vor.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindlicher Two-Step-Pdelay-Ablauf für Ethernet-/gPTP-basierte Zeitsynchronisation in AUTOSAR. Beide Kommunikationspartner müssen Hardware- oder präzise Software-Timestamping-Mechanismen an den Netzwerkschnittstellen unterstützen, um die Egress- und Ingress-Zeitstempel <code>t1</code> bis <code>t4</code> fehlerfrei zuzuordnen. Fehlerzustände (z. B. Timeout beim Ausbleiben von <code>Pdelay_Resp</code> oder <code>Pdelay_Resp_Follow_Up</code>) erfordern gesonderte Behandlungsroutinen.</p>"}, {"id": "FIG-8017864698c40a07", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Signallaufzeitmessung (Propagation Delay Measurement, Pdelay) im AUTOSAR Time Synchronization Protocol (PRS_TimeSyncProtocol / IEEE 802.1AS bzw. gPTP-Mechanismus). Es spezifiziert den nachrichtengestützten Punkt-zu-Punkt-Messablauf zur Bestimmung der Signallaufzeit über eine physikalische Netzwerkverbindung zwischen zwei direkt benachbarten Netzknoten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Peer Delay Initiator</strong>: Messinitiierender Netzknoten (Zeitsynchronisations-Endpunkt oder Switch-Port), sendet die Messanforderung und empfängt Rückmeldungen.</li>\n<li><strong>Peer Delay Responder</strong>: Antwortender Nachbarknoten, nimmt Anforderungen entgegen und übermittelt Messzeitstempel.</li>\n<li><strong>Schnittstellen / Nachrichten</strong>:</li>\n<li><code>Pdelay_Req()</code>: Anforderungsnachricht vom Initiator an den Responder.</li>\n<li><code>Pdelay_Resp(t2)</code>: Antwortnachricht vom Responder an den Initiator mit dem Empfangszeitstempel <code>t2</code>.</li>\n<li><code>Pdelay_Resp_Follow_Up(t3)</code>: Nachfolgenachricht (Two-Step-Verfahren) vom Responder an den Initiator mit dem Sendezeitstempel <code>t3</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <strong>Peer Delay Initiator</strong> erfasst beim Absenden der Anforderung <code>Pdelay_Req()</code> den Sendezeitstempel <code>t1</code> (<code>Get egress timestamp t1</code>).</li>\n<li>Der <strong>Peer Delay Responder</strong> empfängt die Anforderung und erfasst den Eingangszeitstempel <code>t2</code> (<code>Get ingress timestamp t2</code>).</li>\n<li>Der <strong>Peer Delay Responder</strong> sendet die Antwortnachricht <code>Pdelay_Resp(t2)</code> zurück, welche den Zeitstempel <code>t2</code> transportiert, und erfasst beim Absenden den Sendezeitstempel <code>t3</code> (<code>Get egress timestamp t3</code>).</li>\n<li>Der <strong>Peer Delay Initiator</strong> erfasst beim Empfang der Antwortnachricht den lokalen Eingangszeitstempel <code>t4</code> (<code>Get ingress timestamp t4</code>).</li>\n<li>Der <strong>Peer Delay Responder</strong> sendet abschließend die Nachricht <code>Pdelay_Resp_Follow_Up(t3)</code>, die den Zeitstempel <code>t3</code> an den Initiator übermittelt.</li>\n<li>Dem Initiator liegen nach Abschluss des Austauschs alle vier Zeitstempel (<code>t1</code>, <code>t2</code>, <code>t3</code>, <code>t4</code>) zur Berechnung der One-Way-Signallaufzeit (Propagationsverzögerung) vor.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindlicher Two-Step-Pdelay-Ablauf für Ethernet-/gPTP-basierte Zeitsynchronisation in AUTOSAR. Beide Kommunikationspartner müssen Hardware- oder präzise Software-Timestamping-Mechanismen an den Netzwerkschnittstellen unterstützen, um die Egress- und Ingress-Zeitstempel <code>t1</code> bis <code>t4</code> fehlerfrei zuzuordnen. Fehlerzustände (z. B. Timeout beim Ausbleiben von <code>Pdelay_Resp</code> oder <code>Pdelay_Resp_Follow_Up</code>) erfordern gesonderte Behandlungsroutinen.</p>"}, {"id": "FIG-8843e4851b370547", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Signallaufzeitmessung (Propagation Delay Measurement, Pdelay) im AUTOSAR Time Synchronization Protocol (PRS_TimeSyncProtocol / IEEE 802.1AS bzw. gPTP-Mechanismus). Es spezifiziert den nachrichtengestützten Punkt-zu-Punkt-Messablauf zur Bestimmung der Signallaufzeit über eine physikalische Netzwerkverbindung zwischen zwei direkt benachbarten Netzknoten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Peer Delay Initiator</strong>: Messinitiierender Netzknoten (Zeitsynchronisations-Endpunkt oder Switch-Port), sendet die Messanforderung und empfängt Rückmeldungen.</li>\n<li><strong>Peer Delay Responder</strong>: Antwortender Nachbarknoten, nimmt Anforderungen entgegen und übermittelt Messzeitstempel.</li>\n<li><strong>Schnittstellen / Nachrichten</strong>:</li>\n<li><code>Pdelay_Req()</code>: Anforderungsnachricht vom Initiator an den Responder.</li>\n<li><code>Pdelay_Resp(t2)</code>: Antwortnachricht vom Responder an den Initiator mit dem Empfangszeitstempel <code>t2</code>.</li>\n<li><code>Pdelay_Resp_Follow_Up(t3)</code>: Nachfolgenachricht (Two-Step-Verfahren) vom Responder an den Initiator mit dem Sendezeitstempel <code>t3</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <strong>Peer Delay Initiator</strong> erfasst beim Absenden der Anforderung <code>Pdelay_Req()</code> den Sendezeitstempel <code>t1</code> (<code>Get egress timestamp t1</code>).</li>\n<li>Der <strong>Peer Delay Responder</strong> empfängt die Anforderung und erfasst den Eingangszeitstempel <code>t2</code> (<code>Get ingress timestamp t2</code>).</li>\n<li>Der <strong>Peer Delay Responder</strong> sendet die Antwortnachricht <code>Pdelay_Resp(t2)</code> zurück, welche den Zeitstempel <code>t2</code> transportiert, und erfasst beim Absenden den Sendezeitstempel <code>t3</code> (<code>Get egress timestamp t3</code>).</li>\n<li>Der <strong>Peer Delay Initiator</strong> erfasst beim Empfang der Antwortnachricht den lokalen Eingangszeitstempel <code>t4</code> (<code>Get ingress timestamp t4</code>).</li>\n<li>Der <strong>Peer Delay Responder</strong> sendet abschließend die Nachricht <code>Pdelay_Resp_Follow_Up(t3)</code>, die den Zeitstempel <code>t3</code> an den Initiator übermittelt.</li>\n<li>Dem Initiator liegen nach Abschluss des Austauschs alle vier Zeitstempel (<code>t1</code>, <code>t2</code>, <code>t3</code>, <code>t4</code>) zur Berechnung der One-Way-Signallaufzeit (Propagationsverzögerung) vor.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindlicher Two-Step-Pdelay-Ablauf für Ethernet-/gPTP-basierte Zeitsynchronisation in AUTOSAR. Beide Kommunikationspartner müssen Hardware- oder präzise Software-Timestamping-Mechanismen an den Netzwerkschnittstellen unterstützen, um die Egress- und Ingress-Zeitstempel <code>t1</code> bis <code>t4</code> fehlerfrei zuzuordnen. Fehlerzustände (z. B. Timeout beim Ausbleiben von <code>Pdelay_Resp</code> oder <code>Pdelay_Resp_Follow_Up</code>) erfordern gesonderte Behandlungsroutinen.</p>"}], "trans": [{"from": "FIG-57584b453ec449f8", "to": "FIG-8017864698c40a07", "fr": "R1.5.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Grafik: Skalierung bzw. Bildauflösung (869×473 zu 932×507 Pixel) geändert.</li>\n</ul>"}, {"from": "FIG-8017864698c40a07", "to": "FIG-57584b453ec449f8", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Grafik: Skalierung bzw. Bildauflösung (932×507 zu 869×473 Pixel) geändert.</li>\n</ul>"}, {"from": "FIG-57584b453ec449f8", "to": "FIG-8843e4851b370547", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
